package org.kcmcelia.bookofmormon.data

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Mirrors build/manifest.json, which is generated by tools/build_manifest.py.
 * The app never computes chapter positions: everything comes from this file.
 */
@Serializable
data class ContentManifest(
    val schemaVersion: Int = 1,
    val title: String = "",
    val author: String = "",
    val language: String = "zh-HK",
    val counts: Counts = Counts(),
    val books: List<BookRef> = emptyList(),
    val items: List<Chapter> = emptyList(),
) {
    fun chaptersOf(bookIndex: Int): List<Chapter> = items.filter { it.bookIndex == bookIndex }
    fun chapterAt(index: Int): Chapter? = items.firstOrNull { it.index == index }
    val frontMatter: List<Chapter> get() = items.filter { it.bookIndex == null }
}

@Serializable
data class Counts(
    val items: Int = 0,
    val frontmatter: Int = 0,
    val chapters: Int = 0,
    val durationSec: Double = 0.0,
    val bytes: Long = 0,
    val projectedBytesAt32k: Long = 0,
)

@Serializable
data class BookRef(
    val index: Int,
    val name: String,
    val chapters: Int,
    val firstIndex: Int,
    val lastIndex: Int,
)

@Serializable
data class Chapter(
    val index: Int,
    val kind: String = "chapter",
    val bookIndex: Int? = null,
    val bookName: String = "",
    val chapter: Int? = null,
    val displayTitle: String,
    val file: String,
    val bytes: Long = 0,
    val durationSec: Double = 0.0,
    val sha256: String = "",
    val bitrateKbps: Int? = null,
    val sampleRate: Int? = null,
    val channels: String? = null,
    val audioUrl: String? = null,
)

object ManifestLoader {
    private val json = Json { ignoreUnknownKeys = true }

    fun load(context: Context): ContentManifest =
        context.assets.open("manifest.json").bufferedReader().use { reader ->
            json.decodeFromString(ContentManifest.serializer(), reader.readText())
        }
}
